function YouTubeView() {
  const [filterCourse, setFilterCourse] = useState("all");
  const [filterPriority, setFilterPriority] = useState("all");
  
  const courses = [...new Set(YOUTUBE_VIDEOS.map(v => v.courseId))];
  
  let filteredVideos = YOUTUBE_VIDEOS;
  if (filterCourse !== "all") {
    filteredVideos = filteredVideos.filter(v => v.courseId === filterCourse);
  }
  if (filterPriority !== "all") {
    filteredVideos = filteredVideos.filter(v => v.priority === filterPriority);
  }
  
  const getVideoId = (url) => {
    const patterns = [
      /youtu\.be\/([^?]+)/,
      /youtube\.com\/watch\?v=([^&]+)/,
      /youtube\.com\/embed\/([^?]+)/
    ];
    for (const pattern of patterns) {
      const match = url.match(pattern);
      if (match) return match[1];
    }
    return null;
  };
  
  return (
    <div style={{ marginTop: 12 }}>
      <div className="eyebrow">YouTube Links</div>
      <p style={{ color: "var(--text-2)", fontSize: 14, marginTop: 4, marginBottom: 12 }}>
        Essential YouTube videos to watch before end of semester. High priority videos are most important for exams.
      </p>
      
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 16 }}>
        <button 
          className="btn btn-sm" 
          style={{ background: filterCourse === "all" ? "var(--amber)" : "var(--bg-3)", color: filterCourse === "all" ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }}
          onClick={() => setFilterCourse("all")}
        >
          All Courses
        </button>
        {courses.map(c => {
          const course = courseById(c);
          return (
            <button 
              key={c}
              className="btn btn-sm" 
              style={{ background: filterCourse === c ? "var(--amber)" : "var(--bg-3)", color: filterCourse === c ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }}
              onClick={() => setFilterCourse(c)}
            >
              {course ? course.code : c.toUpperCase()}
            </button>
          );
        })}
      </div>
      
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 16 }}>
        <button 
          className="btn btn-sm" 
          style={{ background: filterPriority === "all" ? "var(--amber)" : "var(--bg-3)", color: filterPriority === "all" ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }}
          onClick={() => setFilterPriority("all")}
        >
          All Priorities
        </button>
        <button 
          className="btn btn-sm" 
          style={{ background: filterPriority === "High" ? "var(--amber)" : "var(--bg-3)", color: filterPriority === "High" ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }}
          onClick={() => setFilterPriority("High")}
        >
          High Priority
        </button>
        <button 
          className="btn btn-sm" 
          style={{ background: filterPriority === "Medium" ? "var(--amber)" : "var(--bg-3)", color: filterPriority === "Medium" ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }}
          onClick={() => setFilterPriority("Medium")}
        >
          Medium Priority
        </button>
      </div>
      
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: 16 }}>
        {filteredVideos.map((v) => {
          const course = courseById(v.courseId);
          const videoId = getVideoId(v.url);
          const thumbnailUrl = videoId ? `https://img.youtube.com/vi/${videoId}/mqdefault.jpg` : null;
          
          return (
            <div className="card" key={v.id} style={{ 
              border: v.priority === "High" ? "2px solid var(--amber)" : "1px solid var(--line)",
              padding: 0,
              overflow: "hidden",
              display: "flex",
              flexDirection: "column"
            }}>
              {thumbnailUrl && (
                <div style={{ 
                  position: "relative", 
                  width: "100%", 
                  paddingTop: "56.25%", 
                  background: "var(--bg-3)",
                  overflow: "hidden"
                }}>
                  <img 
                    src={thumbnailUrl} 
                    alt={v.title}
                    style={{
                      position: "absolute",
                      top: 0,
                      left: 0,
                      width: "100%",
                      height: "100%",
                      objectFit: "cover"
                    }}
                    onError={(e) => {
                      e.target.style.display = "none";
                    }}
                  />
                  <div style={{
                    position: "absolute",
                    top: "50%",
                    left: "50%",
                    transform: "translate(-50%, -50%)",
                    width: 56,
                    height: 56,
                    borderRadius: "50%",
                    background: "rgba(255,0,0,0.85)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    cursor: "pointer",
                    transition: "transform 0.2s"
                  }}
                  onMouseEnter={(e) => e.target.style.transform = "translate(-50%, -50%) scale(1.1)"}
                  onMouseLeave={(e) => e.target.style.transform = "translate(-50%, -50%) scale(1)"}
                  onClick={() => window.open(v.url, "_blank")}
                  >
                    <svg width="26" height="26" viewBox="0 0 24 24" fill="white">
                      <path d="M8 5v14l11-7z" />
                    </svg>
                  </div>
                  {v.priority === "High" && (
                    <div style={{
                      position: "absolute",
                      top: 10,
                      right: 10,
                      background: "var(--amber)",
                      color: "#1B1405",
                      padding: "2px 10px",
                      borderRadius: 4,
                      fontSize: 10,
                      fontWeight: 700
                    }}>
                      HIGH
                    </div>
                  )}
                </div>
              )}
              <div style={{ padding: 14, flex: 1, display: "flex", flexDirection: "column" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 4 }}>
                  <div className="eyebrow" style={{ margin: 0, color: "var(--amber)", fontSize: 11 }}>
                    {course ? course.code : v.courseCode}
                  </div>
                  <span style={{ fontSize: 11, color: "var(--text-3)" }}>{v.duration}</span>
                </div>
                <div style={{ fontWeight: 700, fontSize: 15, marginTop: 4, lineHeight: 1.3 }}>{v.title}</div>
                <div style={{ color: "var(--text-3)", fontSize: 12, marginTop: 2 }}>{v.channel}</div>
                <p style={{ color: "var(--text-2)", fontSize: 13, marginTop: 8, lineHeight: 1.5, flex: 1 }}>{v.notes}</p>
                <a 
                  href={v.url} 
                  target="_blank" 
                  rel="noreferrer" 
                  className="btn btn-a btn-sm" 
                  style={{ marginTop: 10, display: "inline-flex", alignItems: "center", gap: 6, textDecoration: "none", alignSelf: "flex-start" }}
                >
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
                    <path d="M8 5v14l11-7z" />
                  </svg>
                  Watch
                </a>
              </div>
            </div>
          );
        })}
      </div>
      
      {filteredVideos.length === 0 && (
        <div className="card" style={{ marginTop: 16 }}>
          <p style={{ color: "var(--text-2)", fontSize: 14 }}>No YouTube videos found for this filter.</p>
        </div>
      )}
    </div>
  );
}
function PapersView({ app }) {
  // PERSISTENCE: Load from sessionStorage on mount
  const [tab, setTab] = useState(() => {
    try {
      const saved = sessionStorage.getItem('ascend_papers_tab');
      return saved || "passco";
    } catch { return "passco"; }
  });
  
  const [courseId, setCourseId] = useState(() => {
    try {
      const saved = sessionStorage.getItem('ascend_papers_course');
      return saved || "ana";
    } catch { return "ana"; }
  });
  
  const [sample, setSample] = useState(() => {
    try {
      const saved = sessionStorage.getItem('ascend_papers_sample');
      return saved || "";
    } catch { return ""; }
  });
  
  const [similarCount, setSimilarCount] = useState(() => {
    try {
      const saved = sessionStorage.getItem('ascend_papers_count');
      const v = saved ? parseInt(saved, 10) : 20;
      return [20, 30, 40, 50].includes(v) ? v : 20;
    } catch { return 20; }
  });

  // Practice set (AI) is fixed at 50 questions, chunked into 10s with
  // mandatory 7/10 mastery gating - no selector, per spec.
  
  const [active, setActive] = useState(() => {
    try {
      const saved = sessionStorage.getItem('ascend_papers_active');
      return saved ? JSON.parse(saved) : null;
    } catch { return null; }
  });
  
  const [items, setItems] = useState(() => {
    try {
      const saved = sessionStorage.getItem('ascend_papers_items');
      return saved ? JSON.parse(saved) : null;
    } catch { return null; }
  });
  
  const [err, setErr] = useState(() => {
    try {
      const saved = sessionStorage.getItem('ascend_papers_err');
      return saved || "";
    } catch { return ""; }
  });
  
  const [busy, setBusy] = useState(false);
  const [passcoNotif, setPasscoNotif] = useState(null);
  const [practiceTopicIdx, setPracticeTopicIdx] = useState("");
  const [practiceActive, setPracticeActive] = useState(false);
  const [similarActive, setSimilarActive] = useState(false);
  
  const count = tab === "solve" ? 50 : similarCount;
  const CHUNK = 50;
  
  // SAVE: Persist all state changes
  useEffect(() => {
    try {
      sessionStorage.setItem('ascend_papers_tab', tab);
      sessionStorage.setItem('ascend_papers_course', courseId);
      sessionStorage.setItem('ascend_papers_sample', sample);
      sessionStorage.setItem('ascend_papers_count', String(similarCount));
      if (active) sessionStorage.setItem('ascend_papers_active', JSON.stringify(active));
      if (items) sessionStorage.setItem('ascend_papers_items', JSON.stringify(items));
      if (err) sessionStorage.setItem('ascend_papers_err', err);
    } catch {}
  }, [tab, courseId, sample, similarCount, active, items, err]);
  
  // Save PapersView state when it changes
  useEffect(() => {
    try {
      const state = {
        tab,
        courseId,
        sample,
        similarCount,
        active,
        items,
        err,
        busy
      };
      sessionStorage.setItem('ascend_papers_state', JSON.stringify(state));
    } catch (error) {
      // Silently fail
    }
  }, [tab, courseId, sample, similarCount, active, items, err, busy]);

  // Restore PapersView state on mount
  useEffect(() => {
    try {
      const saved = sessionStorage.getItem('ascend_papers_state');
      if (saved) {
        const state = JSON.parse(saved);
        if (state.tab) setTab(state.tab);
        if (state.courseId) setCourseId(state.courseId);
        if (state.sample !== undefined) setSample(state.sample);
        if (state.similarCount) setSimilarCount(state.similarCount);
        if (state.active) setActive(state.active);
        if (state.items) setItems(state.items);
        if (state.err) setErr(state.err);
      }
    } catch (error) {
      // Silently fail
    }
  }, []);
  
  // Load passco notification
  useEffect(() => {
    try {
      const stored = sessionStorage.getItem('ascend_passco_notif');
      if (stored) {
        const parsed = JSON.parse(stored);
        setPasscoNotif(parsed);
        setTimeout(function() {
          setPasscoNotif(null);
          sessionStorage.removeItem('ascend_passco_notif');
        }, 5000);
      }
    } catch (error) {
      // Silently fail
    }
  }, []);
  
  const RULES = "Rules: single best-answer MCQs, recall and understanding, NO diagrams. Make all four options similar in length and equally plausible so the answer is never obvious. Vary which option is correct across questions. No repeats. Return ONLY a JSON array - no prose, no markdown. Each item: {\"q\": string, \"o\": [4 strings], \"correct\": the exact text of the correct option copied verbatim from \"o\", \"w\": one short explanation}.  ACCURACY IS CRITICAL: for EACH question, independently work out the correct answer from your own subject knowledge and set \"correct\" to exactly that option. If two options could both be defended, rewrite the question so exactly one is unambiguously correct. Never mark an answer you are not fully certain is factually correct - if unsure, replace that question with one whose answer you are certain of. The one-line explanation in \"w\" must justify why \"correct\" is right.";
  
  const shuffleOptions = function(arr) {
    return arr.map(function(item) {
      var opts = item.o.map(function(text, i) {
        return { text: text, correct: i === item.a };
      });
      for (var pass = 0; pass < 3; pass++) {
        for (var i = opts.length - 1; i > 0; i--) {
          var j = Math.floor(Math.random() * (i + 1));
          var temp = opts[i];
          opts[i] = opts[j];
          opts[j] = temp;
        }
      }
      return {
        q: item.q,
        o: opts.map(function(x) { return x.text; }),
        a: opts.findIndex(function(x) { return x.correct; }),
        w: item.w
      };
    });
  };
  
  const genSet = async function(usr) {
  if (busy) return;
  setBusy(true);
  setErr("");
  setItems(null);
  
  let attempts = 0;
  const BATCH_SIZE = 12; // keep each call small enough to finish inside the server's per-request timeout
  const maxAttempts = Math.max(3, Math.ceil(count / BATCH_SIZE) * 2);
  let allQuestions = [];
  
  while (attempts < maxAttempts && allQuestions.length < count) {
    attempts++;
    const remaining = count - allQuestions.length;
    const thisBatch = Math.min(BATCH_SIZE, remaining);
    try {
      const text = await callClaude(
        "You generate KNUST-style medical laboratory science exam questions based on the specific course content provided. Return ONLY a valid, compact, complete JSON array of exactly " + thisBatch + " questions, no prose, no markdown, no trailing commas. Keep each question and option short. Every question must have exactly one unambiguously correct option - double-check your \"correct\" field matches one of the four options verbatim.",
        [{ role: "user", content: usr.replace(/exactly \d+/, "exactly " + thisBatch) }],
        Math.min(4000, thisBatch * 300 + 500)
      );
      const arr = parseAIJson(text);
      const filtered = (Array.isArray(arr) ? arr : []).map(resolveMcqAnswer).filter(Boolean);
      
      if (filtered.length > 0) {
        // Add to collection and remove duplicates
        allQuestions = [...allQuestions, ...filtered];
        const seen = new Set();
        allQuestions = allQuestions.filter(function(item) {
          const key = item.q.toLowerCase().trim();
          if (seen.has(key)) return false;
          seen.add(key);
          return true;
        });
      }
      
      // If we have enough, break out
      if (allQuestions.length >= count) break;
      
    } catch (error) {
      // Continue to next attempt
    }
  }
  
  if (!allQuestions.length) {
    setErr("No usable questions came back - please try again.");
    setBusy(false);
    return;
  }
  
  // FIX: Accept what we have with warning if less than requested
  if (allQuestions.length < count) {
    const shuffled = shuffleOptions(allQuestions);
    setItems(shuffled);
    setErr("Generated " + allQuestions.length + " questions (requested " + count + "). You can still practice with these.");
  } else {
    setItems(shuffleOptions(allQuestions.slice(0, count)));
  }
  
  setBusy(false);
};
  const startSolve = function() {
    var topics = TOPICS[courseId] || [];
    var topicNames = topics.slice(0, 8).join(", ");
    var contentSample = "";
    for (var i = 0; i < Math.min(3, topics.length); i++) {
      var t = contentFor(courseId, i);
      if (t) {
        var noteText = (t.note || []).slice(0, 3).map(function(n) { return n.q; }).join("; ");
        contentSample += "Topic " + (i+1) + ": " + t.title + ". Key concepts: " + noteText + "\n";
      }
    }
    genSet("Generate exactly " + count + " passco-style exam MCQs for a KNUST first-year student in " + courseById(courseId).name + " (" + courseById(courseId).code + ").\n\nIMPORTANT: Questions MUST be based on these specific topics: " + topicNames + "\n\nHere is sample content from the course to guide you:\n" + contentSample + "\n\nGenerate questions that test understanding of these specific topics. Do not ask general anatomy questions.\n\n" + RULES);
  };
  
  const startSimilar = function() {
    genSet("Here is a passco question:\n\n" + sample + "\n\nGenerate exactly " + count + " fresh MCQs testing the same concept and matching its style, for " + courseById(courseId).name + ". " + RULES);
  };
  
  return (
    <div className="view">
      {/* PASSCO XP NOTIFICATION */}
      {passcoNotif && (
        <div className="card" style={{
          marginBottom: 12,
          padding: "10px 16px",
          borderColor: "#2E9BFF",
          borderWidth: 1,
          background: "rgba(46,155,255,0.08)",
          display: "flex",
          alignItems: "center",
          gap: 10
        }}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#2E9BFF" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 2L2 7l10 5 10-5-10-5z" />
            <path d="M2 17l10 5 10-5" />
            <path d="M2 12l10 5 10-5" />
          </svg>
          <div>
            <span style={{ fontWeight: 600, color: "#2E9BFF" }}>+{passcoNotif.earned} XP</span>
            <span style={{ color: "var(--text-2)", fontSize: 13.5, marginLeft: 6 }}>from past paper practice</span>
          </div>
        </div>
      )}
      
      <div className="eyebrow">Passco</div>
      <h1 style={{ fontSize: "clamp(22px,4vw,28px)", margin: "6px 0 4px" }}>Solve them, don't just stare at the PDF</h1>
      <p style={{ color: "var(--text-2)", marginTop: 0, maxWidth: "58ch" }}>A passco PDF is easy to put off. Here you actually answer, tap by tap, with instant feedback - and ASCEND can spin fresh questions off any one you show it.</p>
      
      <div className="tabs">
        <button className={"tab " + (tab === "passco" ? "on" : "")} onClick={function() { setTab("passco"); setItems(null); setErr(""); setActive(null); setPracticeActive(false); setSimilarActive(false); }}>Passco</button>
        <button className={"tab " + (tab === "solve" ? "on" : "")} onClick={function() { setTab("solve"); setItems(null); setErr(""); setSimilarActive(false); }}>Practice set (AI)</button>
        <button className={"tab " + (tab === "similar" ? "on" : "")} onClick={function() { setTab("similar"); setItems(null); setErr(""); setPracticeActive(false); }}>Generate similar</button>
        <button className={"tab " + (tab === "youtube" ? "on" : "")} onClick={function() { setTab("youtube"); setItems(null); setErr(""); setPracticeActive(false); setSimilarActive(false); }}>YouTube Links</button>
      </div>

      {tab === "passco" && (active
        ? <PasscoSet paper={active.paper} chunkStart={active.chunkStart} chunkEnd={active.chunkEnd} mode={active.mode} onExit={function() { setActive(null); }} app={app} />
        : <PasscoPicker onStart={function(paper, chunkStart, chunkEnd, mode) { setActive({ paper: paper, chunkStart: chunkStart, chunkEnd: chunkEnd, mode: mode }); try { window.scrollTo({ top: 0, behavior: "smooth" }); } catch (error) {} }} chunk={CHUNK} passcoScores={app.progress.passcoScores} />
      )}

      {tab === "youtube" && (
        <YouTubeView />
      )}

      {(tab !== "passco" && tab !== "youtube" && !(tab === "solve" && practiceActive) && !(tab === "similar" && similarActive)) && (
        <div className="card" style={{ marginTop: 12 }}>
          <label className="eyebrow" style={{ display: "block", marginBottom: 8 }}>Course</label>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: tab === "similar" ? 16 : 4 }}>
            {COURSES.map(function(c) {
              return (
                <button key={c.id} className="btn btn-sm" style={{ background: courseId === c.id ? "var(--amber)" : "var(--bg-3)", color: courseId === c.id ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }} onClick={function() { setCourseId(c.id); setPracticeTopicIdx(""); }}>{c.code}</button>
              );
            })}
          </div>
          {tab === "solve" && (TOPICS[courseId] || []).length > 0 && (
            <>
              <label className="eyebrow" style={{ display: "block", margin: "12px 0 8px" }}>Which topic? <span style={{ color: "var(--text-3)", fontWeight: 400, fontSize: 12 }}>(leave blank for a mix of all topics)</span></label>
              <select className="auth-input" value={practiceTopicIdx} onChange={function(e) { setPracticeTopicIdx(e.target.value); }}>
                <option value="">All topics mixed</option>
                {(TOPICS[courseId] || []).map(function(title, idx) {
                  return <option key={idx} value={String(idx)}>{title}</option>;
                })}
              </select>
            </>
          )}
          {tab === "similar" && (
            <>
              {(TOPICS[courseId] || []).length > 0 && (
                <>
                  <label className="eyebrow" style={{ display: "block", marginBottom: 8 }}>Which topic? <span style={{ color: "var(--text-3)", fontWeight: 400, fontSize: 12 }}>(leave blank for a mix of all topics)</span></label>
                  <select className="auth-input" value={practiceTopicIdx} onChange={function(e) { setPracticeTopicIdx(e.target.value); }}>
                    <option value="">All topics mixed</option>
                    {(TOPICS[courseId] || []).map(function(title, idx) {
                      return <option key={idx} value={String(idx)}>{title}</option>;
                    })}
                  </select>
                </>
              )}
              <label className="eyebrow" style={{ display: "block", margin: "16px 0 8px" }}>Paste one passco question</label>
              <textarea className="pastebox" value={sample} placeholder={"e.g.\n\nThe plane dividing the body into left and right is the\nA. coronal  B. sagittal  C. transverse  D. oblique"} onChange={function(e) { setSample(e.target.value); }} />
              <label className="eyebrow" style={{ display: "block", margin: "16px 0 8px" }}>How many similar questions?</label>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>{[20, 30, 40, 50].map(function(n) {
                return <button key={n} className="btn btn-sm" style={{ background: similarCount === n ? "var(--amber)" : "var(--bg-3)", color: similarCount === n ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)", minWidth: 48 }} onClick={function() { setSimilarCount(n); }}>{n}</button>;
              })}</div>
              <div style={{ marginTop: 12 }}>
                <span style={{ fontSize: 13.5, color: "var(--text-2)" }}>Requires 7/10 to advance - any question you miss, you redo right away until you get it right.</span>
              </div>
            </>
          )}
          {/* CHANGED: Different messages for practice vs similar */}
          {tab === "solve" && (
            <>
              <div style={{ color: "var(--text-2)", marginTop: 4, fontSize: 14, lineHeight: 1.6 }}>50 questions total, delivered in sets of 10 with rising difficulty. You must score 7/10 to unlock the next set - any question you miss, you redo immediately until you get it right, then you move on.</div>
            </>
          )}
          {tab === "similar" && (
            <div style={{ color: "var(--text-2)", marginTop: 16, fontSize: 14 }}>ASCEND builds this in sets of 10 so it never stalls - {similarCount} questions total, delivered as you go.</div>
          )}
          <div style={{ marginTop: 16 }}>
            {tab === "solve"
              ? <button className="btn btn-a" onClick={function() { setPracticeActive(true); }}>Generate 50 with AI <Ic.ai p={16} /></button>
              : <button className="btn btn-a" onClick={function() { if (!sample.trim()) { setErr("Paste a passco question above first, then generate."); return; } setErr(""); setSimilarActive(true); }}>Generate {similarCount} similar <Ic.ai p={16} /></button>}
          </div>
        </div>
      )}
      {tab === "solve" && practiceActive && (
        <ChunkedPracticeSet
          course={courseById(courseId)}
          topicName={practiceTopicIdx !== "" ? (TOPICS[courseId] || [])[parseInt(practiceTopicIdx, 10)] : null}
          total={50}
          requireMastery={true}
          onExit={function() { setPracticeActive(false); }}
          finishQuiz={app.finishQuiz}
        />
      )}
      {tab === "similar" && similarActive && (
        <ChunkedPracticeSet
          course={courseById(courseId)}
          topicName={practiceTopicIdx !== "" ? (TOPICS[courseId] || [])[parseInt(practiceTopicIdx, 10)] : null}
          sampleQuestion={sample}
          total={similarCount}
          requireMastery={true}
          onExit={function() { setSimilarActive(false); }}
          finishQuiz={app.finishQuiz}
        />
      )}
      {tab !== "passco" && tab !== "youtube" && tab !== "solve" && err && <div className="card" style={{ marginTop: 14, borderColor: "var(--line-2)", color: "var(--text-2)", fontSize: 14 }}>{err}</div>}
      {tab !== "passco" && tab !== "youtube" && tab !== "solve" && busy && <div className="card" style={{ marginTop: 14 }}><span className="dots"><span /><span /><span /></span></div>}
      {tab !== "passco" && tab !== "youtube" && tab !== "solve" && items && <InteractiveSet key={items.map(function(x) { return x.q; }).join("|").length + "-" + items.length} items={items} />}
    </div>
  );
}

/* PasscoPicker: lists real past papers (grouped by course), and lets the student
   pick a 50-question chunk and a mode (practice or exam). Chunking keeps sets to
   50 so a 100+ question paper never overwhelms - you solve 50, then the next 50. */
function PasscoPicker({ onStart, chunk, passcoScores }) {
  const scores = passcoScores || {};
  const [openPaper, setOpenPaper] = useState(null);
  const [mode, setMode] = useState("practice");
  if (!PAST_PAPERS.length) {
    return <div className="card" style={{ marginTop: 12, color: "var(--text-2)", fontSize: 14 }}>No passco papers uploaded yet. They will appear here as they are added.</div>;
  }
  return (
    <div style={{ marginTop: 12 }}>
      <p style={{ color: "var(--text-2)", fontSize: 14, marginTop: 0 }}>Real passco papers, worked out and turned into tap-to-answer questions. Long papers are split into sets of {chunk} so you never burn out - finish one set, then the next.</p>
      {PAST_PAPERS.map(function(paper) {
        var nChunks = Math.ceil(paper.questions.length / chunk);
        var isOpen = openPaper === paper.id;
        return (
          <div className="card" key={paper.id} style={{ marginBottom: 10 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12 }}>
              <div style={{ minWidth: 0, flex: 1 }}>
                <div className="eyebrow" style={{ margin: 0 }}>{paper.courseCode} · {paper.year}</div>
                <div style={{ fontWeight: 650, fontSize: 15.5, marginTop: 2 }}>{paper.title}</div>
                <div style={{ color: "var(--text-3)", fontSize: 13, marginTop: 2 }}>{paper.questions.length} questions · {nChunks} set{nChunks > 1 ? "s" : ""} of up to {chunk}</div>
                {paper.note && <div style={{ color: "var(--text-3)", fontSize: 12.5, marginTop: 4, maxWidth: "100%" }}>{paper.note}</div>}
              </div>
              <button className="btn btn-sm" style={{ background: isOpen ? "var(--bg-3)" : "var(--amber)", color: isOpen ? "var(--text-2)" : "#1B1405", border: "1px solid var(--line)", flexShrink: 0, whiteSpace: "nowrap", alignSelf: "center" }} onClick={function() { setOpenPaper(isOpen ? null : paper.id); }}>{isOpen ? "Close" : "Open"}</button>
            </div>
            {isOpen && (
              <div style={{ marginTop: 14, borderTop: "1px solid var(--line)", paddingTop: 14 }}>
                <label className="eyebrow" style={{ display: "block", marginBottom: 8 }}>Mode</label>
                <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap" }}>
                  <button className="btn btn-sm" style={{ background: mode === "practice" ? "var(--amber)" : "var(--bg-3)", color: mode === "practice" ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }} onClick={function() { setMode("practice"); }}>Practice</button>
                  <button className="btn btn-sm" style={{ background: mode === "exam" ? "var(--amber)" : "var(--bg-3)", color: mode === "exam" ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }} onClick={function() { setMode("exam"); }}>Exam</button>
                </div>
                <div style={{ fontSize: 12.5, color: "var(--text-3)", marginBottom: 14 }}>{mode === "practice" ? "Practice: the correct answer and explanation show the instant you tap." : "Exam: answers stay hidden until you submit, then you get your score and full review."}</div>
                <label className="eyebrow" style={{ display: "block", marginBottom: 8 }}>Choose a set</label>
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                  {Array.from({ length: nChunks }).map(function(_, i) {
                    var start = i * chunk;
                    var end = Math.min(start + chunk, paper.questions.length);
                    var sk = `${paper.id}_${start}_${end}_${mode}`;
                    var prevScore = scores[sk];
                    return (
                      <button key={i} className="btn btn-sm" style={{ background: "var(--bg-3)", color: "var(--text-2)", border: "1px solid " + (prevScore ? "var(--amber)" : "var(--line)"), display: "flex", flexDirection: "column", alignItems: "center", gap: 2, lineHeight: 1.2, position: "relative" }} onClick={function() { onStart(paper, start, end, mode); }}>
                        {prevScore && prevScore.pct >= 70 && <span style={{ position: "absolute", top: -6, right: -6, width: 14, height: 14, borderRadius: "50%", background: "var(--good)", color: "#08210F", fontSize: 9.5, display: "flex", alignItems: "center", justifyContent: "center", lineHeight: 1 }}>✓</span>}
                        <span>Q{start + 1}-{end}</span>
                        {prevScore && <span className="mono" style={{ fontSize: 10.5, color: prevScore.pct >= 70 ? "var(--good)" : "var(--amber-2)" }}>{prevScore.pct}%</span>}
                      </button>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

/* PasscoSet: renders one chunk of a real past paper as tap-to-answer questions.
   Practice mode reveals the answer + explanation the instant you tap (like the
   AI-generated sets). Exam mode hides answers until you submit the whole set,
   then shows your score and a full review. Awards XP once per set via
   app.setPasscoXp, guarded so re-opening a finished set never double-pays. */
function PasscoSet({ paper, chunkStart, chunkEnd, mode, onExit, app }) {
  const questions = paper.questions.slice(chunkStart, chunkEnd);
  const setKey = `${paper.id}_${chunkStart}_${chunkEnd}_${mode}`;
  const doneFlagKey = "ascend_passco_done_" + setKey;

  // Lets a student flag a specific Passco question whose stored correct
  // answer looks wrong (e.g. the explanation clearly supports a different
  // option than the one marked correct). Reports are deduped per-device per
  // question (localStorage) and written to shared storage so they surface
  // in the admin Feedback viewer for review and correction.
  const questionReportKey = (it) => "ascend_qreport_sent_" + questionKey(it);
  // Hydrate from localStorage on mount so a question reported in an earlier
  // session still shows "flagged for review" instead of the button again -
  // reportQuestionIssue already no-ops on a re-click, but without this the
  // UI would misleadingly imply nothing had been reported yet.
  const [reportedIds, setReportedIds] = useState(() => {
    const initial = {};
    try {
      for (const it of questions) {
        if (localStorage.getItem("ascend_qreport_sent_" + questionKey(it))) {
          initial[questionKey(it)] = true;
        }
      }
    } catch {}
    return initial;
  });
  const reportQuestionIssue = async (it, chosenIdx) => {
    const localKey = questionReportKey(it);
    let already = false;
    try { already = !!localStorage.getItem(localKey); } catch {}
    if (already) return;
    try { localStorage.setItem(localKey, "true"); } catch {}
    setReportedIds((r) => ({ ...r, [questionKey(it)]: true }));
    try {
      await store.setShared("ascend_qreport:" + Date.now() + "_" + Math.random().toString(36).slice(2, 8), {
        type: "passco_answer",
        courseId: paper.courseId,
        courseCode: paper.courseCode,
        paperTitle: paper.title,
        question: it.q,
        options: it.o,
        storedAnswerIndex: it.a,
        storedAnswerText: it.o[it.a],
        studentChosenIndex: chosenIdx,
        studentChosenText: chosenIdx !== undefined ? it.o[chosenIdx] : null,
        explanation: it.w,
        timestamp: new Date().toISOString(),
      });
    } catch (e) { /* best-effort - don't block the student's flow on this */ }
  };

  const [picked, setPicked] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [cur, setCur] = useState(0); // index of the current question being shown
  const awardedRef = useRef(false);

  const answered = Object.keys(picked).length;
  const allAnswered = answered === questions.length;
  const correctCount = questions.reduce((n, it, idx) => n + (picked[idx] === it.a ? 1 : 0), 0);

  const award = () => {
    if (awardedRef.current) return;
    let already = false;
    try { already = !!sessionStorage.getItem(doneFlagKey); } catch {}
    if (already) { awardedRef.current = true; return; }
    awardedRef.current = true;
    try { sessionStorage.setItem(doneFlagKey, "true"); } catch {}
    if (app && typeof app.setPasscoXp === "function") {
      app.setPasscoXp(correctCount * 5, setKey, correctCount, questions.length);
    }
    if (app && typeof app.addMissedToReview === "function") {
      const missed = questions
        .map((it, idx) => ({ it, chosen: picked[idx] }))
        .filter(({ it, chosen }) => chosen !== undefined && chosen !== it.a)
        .map(({ it }) => ({ q: it.q, o: it.o, a: it.a, w: it.w, topic: paper.title, courseId: paper.courseId }));
      app.addMissedToReview(missed);
    }
  };

  // Practice mode: award as soon as every question in the set has been answered.
  useEffect(() => {
    if (mode === "practice" && allAnswered && questions.length > 0) award();
  }, [allAnswered, mode]);

  const pick = (idx, oi) => {
    if (mode === "practice") {
      if (picked[idx] !== undefined) return;
      setPicked((p) => ({ ...p, [idx]: oi }));
    } else {
      if (submitted) return;
      setPicked((p) => ({ ...p, [idx]: oi }));
    }
  };

  const submitExam = () => {
    setSubmitted(true);
    award();
    try { window.scrollTo({ top: 0, behavior: "smooth" }); } catch {}
  };

  // Navigate between questions WITHOUT forcing the page back to the top. The
  // scroll position stays exactly where the student left it (persistent), so
  // answering and tapping Next no longer yanks the view up to the question
  // navigator - the page only moves if the student scrolls it themselves.
  const go = (i) => { setCur(Math.max(0, Math.min(questions.length - 1, i))); };
  const letters = "ABCDE";

  const hasAR = questions.some((it) => / BECAUSE /i.test(it.q || "")) && paper.courseId === "bch";
  const arIsFiveWay = hasAR && questions.some((it) => (it.o || []).some((o) => /correct explanation/i.test(o)));
  const [showTip, setShowTip] = useState(true);

  // ===== EXAM REVIEW SCREEN: after submit, show every question marked =====
  if (mode === "exam" && submitted) {
    const pct = questions.length ? Math.round((correctCount / questions.length) * 100) : 0;
    return (
      <div style={{ marginTop: 12 }}>
        <button className="back" onClick={onExit}><Ic.chevR p={15} style={{ transform: "rotate(180deg)" }} /> Back to sets</button>
        <div className="card" style={{ marginTop: 12, marginBottom: 12, textAlign: "center", borderColor: "var(--amber)" }}>
          <div className="eyebrow">Your score</div>
          <div style={{ fontSize: 36, fontWeight: 800, color: pct >= 50 ? "var(--good)" : "var(--bad)", margin: "4px 0" }}>{pct}%</div>
          <div style={{ color: "var(--text-2)", fontSize: 14 }}>{correctCount} out of {questions.length} correct · {paper.courseCode} · Q{chunkStart + 1}-{chunkEnd}</div>
        </div>
        {questions.map((it, idx) => {
          const chosen = picked[idx];
          return (
            <div className="card" key={idx} style={{ marginBottom: 10 }}>
              <div style={{ fontWeight: 600, marginBottom: 10 }}><span className="mono" style={{ color: "var(--text-3)" }}>{String(chunkStart + idx + 1).padStart(2, "0")}. </span>{it.q}{it.flag && <span style={{ marginLeft: 6, fontSize: 11, color: "var(--amber-2)", border: "1px solid var(--line-2)", borderRadius: 4, padding: "1px 5px" }}>verify</span>}</div>
              {it.img && <div style={{ margin: "0 0 12px", textAlign: "center" }}><img src={it.img} alt="Molecule for this question" loading="lazy" style={{ maxWidth: "100%", maxHeight: 260, borderRadius: 8, background: "#fff", padding: 8, border: "1px solid var(--line)" }} /></div>}
              {it.o.map((opt, oi) => {
                let cls = "opt";
                if (oi === it.a) cls += " correct"; else if (oi === chosen) cls += " wrong";
                return <div className={cls} key={oi} style={{ cursor: "default" }}><span className="key">{letters[oi] || oi + 1}</span><span>{opt}</span></div>;
              })}
              <div style={{ color: "var(--text-2)", fontSize: 13.5, marginTop: 8 }}><strong style={{ color: chosen === it.a ? "var(--good)" : "var(--bad)" }}>{chosen === undefined ? "Not answered. " : (chosen === it.a ? "Correct. " : "Your answer: " + (letters[chosen] || "") + ". ")}</strong>{chosen !== it.a && "Answer: " + (letters[it.a] || "") + ". "}{it.w}</div>
              {reportedIds[questionKey(it)] ? (
                <div style={{ marginTop: 8, fontSize: 12, color: "var(--text-3)" }}>Thanks - flagged for review.</div>
              ) : (
                <button className="btn btn-g" style={{ marginTop: 8, padding: "6px 10px", fontSize: 12 }} onClick={() => reportQuestionIssue(it, chosen)}>Report wrong answer</button>
              )}
            </div>
          );
        })}
        <button className="btn btn-g" onClick={onExit} style={{ marginTop: 4 }}>Back to sets</button>
      </div>
    );
  }

  // ===== ONE-QUESTION-AT-A-TIME CBT VIEW =====
  const it = questions[cur];
  const chosen = picked[cur];
  const revealHere = mode === "practice" ? chosen !== undefined : false;

  return (
    <div style={{ marginTop: 12 }}>
      <button className="back" onClick={onExit}><Ic.chevR p={15} style={{ transform: "rotate(180deg)" }} /> Back to sets</button>

      <div className="card" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12, marginBottom: 12, flexWrap: "wrap", gap: 8 }}>
        <div>
          <div className="eyebrow" style={{ margin: 0 }}>{paper.courseCode} · {paper.title}</div>
          <div style={{ color: "var(--text-3)", fontSize: 13, marginTop: 2 }}>Q{chunkStart + 1}-{chunkEnd} · {mode === "practice" ? "Practice" : "Exam"} · question {cur + 1} of {questions.length}</div>
        </div>
        <div className="mono" style={{ fontWeight: 700 }}>
          {mode === "practice" ? <span><span style={{ color: "var(--amber)" }}>{correctCount}</span> / {answered}</span> : <span style={{ color: "var(--text-3)" }}>{answered}/{questions.length}</span>}
        </div>
      </div>

      {hasAR && showTip && (
        <div className="card" style={{ marginBottom: 12, borderColor: "var(--amber)" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
            <div className="eyebrow" style={{ margin: 0 }}>Assertion-reason: how to read it</div>
            <button onClick={() => setShowTip(false)} style={{ background: "none", border: "none", color: "var(--text-3)", cursor: "pointer", fontSize: 13, padding: 0 }}>Hide</button>
          </div>
          <p style={{ color: "var(--text-2)", fontSize: 13.5, lineHeight: 1.6, margin: "8px 0 0" }}>
            Each question has two statements: <strong>statement 1</strong> (the assertion) and <strong>statement 2</strong> (the reason, after "BECAUSE"). Judge them separately first - is each one true or false on its own? Only once both are true do you ask: does statement 2 actually explain <em>why</em> statement 1 is true?
          </p>
          {arIsFiveWay ? (
            <p style={{ color: "var(--text-2)", fontSize: 13.5, lineHeight: 1.7, margin: "10px 0 0" }}>
              <strong>A</strong> - both true, 2 explains 1 · <strong>B</strong> - both true, 2 does NOT explain 1 · <strong>C</strong> - 1 true, 2 false · <strong>D</strong> - 1 false, 2 true · <strong>E</strong> - both false.
            </p>
          ) : (
            <p style={{ color: "var(--text-2)", fontSize: 13.5, lineHeight: 1.6, margin: "10px 0 0" }}>
              This set uses True / False / Neither / Both instead of the 5-way code - read the options as given rather than assuming the A-E scheme.
            </p>
          )}
        </div>
      )}

      {/* Question navigator grid - tap any number to jump */}
      <div className="card" style={{ marginBottom: 12, padding: "12px 14px" }}>
        <div className="eyebrow" style={{ marginBottom: 8 }}>Question navigator</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
          {questions.map((_, i) => {
            const isAns = picked[i] !== undefined;
            const isCur = i === cur;
            let bg = "var(--bg-3)", col = "var(--text-3)", bd = "var(--line)";
            if (isAns) { bg = "var(--amber-dim)"; col = "var(--amber-2)"; bd = "var(--amber)"; }
            if (isCur) { bg = "var(--amber)"; col = "#1B1405"; bd = "var(--amber)"; }
            return <button key={i} onClick={() => go(i)} className="mono" style={{ width: 32, height: 32, borderRadius: 7, border: "1px solid " + bd, background: bg, color: col, fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>{chunkStart + i + 1}</button>;
          })}
        </div>
      </div>

      {/* The single current question */}
      <div className="card" style={{ marginBottom: 12 }}>
        <div style={{ fontWeight: 600, marginBottom: 12, fontSize: 15.5 }}>
          <span className="mono" style={{ color: "var(--text-3)" }}>{String(chunkStart + cur + 1).padStart(2, "0")}. </span>{it.q}
          {it.flag && <span title="Tricky specimen question - verify the intended answer with your lecturer" style={{ marginLeft: 6, fontSize: 11, color: "var(--amber-2)", border: "1px solid var(--line-2)", borderRadius: 4, padding: "1px 5px" }}>verify</span>}
        </div>
        {it.img && <div style={{ margin: "0 0 14px", textAlign: "center" }}><img src={it.img} alt="Molecule for this question" loading="lazy" style={{ maxWidth: "100%", maxHeight: 300, borderRadius: 8, background: "#fff", padding: 8, border: "1px solid var(--line)" }} /></div>}
        {it.o.map((opt, oi) => {
          let cls = "opt";
          if (revealHere) { if (oi === it.a) cls += " correct"; else if (oi === chosen) cls += " wrong"; }
          else if (chosen === oi) cls += " chosen";
          const lock = mode === "practice" && chosen !== undefined;
          return (
            <button className={cls} key={oi} disabled={lock} onClick={() => pick(cur, oi)}>
              <span className="key">{letters[oi] || oi + 1}</span><span>{opt}</span>
            </button>
          );
        })}
        {revealHere && chosen !== undefined && (
          <div style={{ color: "var(--text-2)", fontSize: 13.5, marginTop: 10 }}>
            <strong style={{ color: chosen === it.a ? "var(--good)" : "var(--bad)" }}>{chosen === it.a ? "Correct. " : "Answer: " + (letters[it.a] || "") + ". "}</strong>{it.w}
          </div>
        )}
        {revealHere && chosen !== undefined && (
          reportedIds[questionKey(it)] ? (
            <div style={{ marginTop: 8, fontSize: 12, color: "var(--text-3)" }}>Thanks - flagged for review.</div>
          ) : (
            <button className="btn btn-g" style={{ marginTop: 8, padding: "6px 10px", fontSize: 12 }} onClick={() => reportQuestionIssue(it, chosen)}>Report wrong answer</button>
          )
        )}
      </div>

      {/* Navigation controls */}
      <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
        <button className="btn btn-g" onClick={() => go(cur - 1)} disabled={cur === 0}>Previous</button>
        {cur < questions.length - 1
          ? <button className="btn btn-a" onClick={() => go(cur + 1)}>Next question</button>
          : (mode === "exam"
              ? <button className="btn btn-a" onClick={submitExam} disabled={answered === 0}>Submit exam ({answered}/{questions.length})</button>
              : <button className="btn btn-a" onClick={onExit}>Finish set</button>)}
        <button className="btn btn-g" onClick={onExit} style={{ marginLeft: "auto" }}>Exit</button>
      </div>

      {mode === "practice" && allAnswered && (
        <div className="card" style={{ marginTop: 12, textAlign: "center" }}>
          <div className="eyebrow" style={{ margin: 0 }}>Set complete</div>
          <div style={{ fontSize: 20, fontWeight: 700, margin: "6px 0" }}>{correctCount} / {questions.length} correct</div>
          <button className="btn btn-g" onClick={onExit}>Back to sets</button>
        </div>
      )}
    </div>
  );
}
/* ------------------------------- resources ------------------------------ */
const SOCRATIC_SYS = "You are the ASCEND Socratic tutor for KNUST medical laboratory science students. Break material into a sequential continuum of knowledge: pose a question, give a hint, then answer it fully in flowing paragraphs, then state the crucial insight or clinical pearl. Teach mechanism over memorisation. No emojis. Write all mathematics and numbers in plain readable text. NEVER use LaTeX, markdown math, dollar signs, backslashes, or fraction commands. Use the caret ^ for exponents (e.g. 10^3 - the app will convert it to superscript). Use 'x' for multiplication. Write fractions as 'a/b' or in words. Never output symbols like $, \\times, or \\frac. Accuracy is critical - these are medical facts students will be examined on. Only state specific numbers, values, classifications, enzyme names, or mechanisms you are confident are correct. If you are not certain of an exact figure or detail, describe the concept accurately without inventing a precise number.";
const SOCRATIC_TASK = "Break this study material into a focused Socratic lesson of 4 to 6 steps. For each step: state the question, explain the answer in one or two clear paragraphs, then give the crucial insight in one line. End with three short self-test questions and their answers. Be economical so the whole lesson is complete and never cut off.";

// ============================================================
// PDF.js loader - extracts text from PDFs client-side
// ============================================================
let _pdfjsPromise = null;

function loadPDFJS() {
  if (typeof window === "undefined") return Promise.reject(new Error("no window"));
  if (window.pdfjsLib) return Promise.resolve(window.pdfjsLib);
  if (_pdfjsPromise) return _pdfjsPromise;

  // Try a couple of CDN mirrors in case one is down or the version got
  // pulled/renamed - and never cache a failed load, so the next attempt
  // (next upload, or a retry) gets a fresh shot instead of being stuck
  // permanently failing for the rest of the session.
  const CDN_SOURCES = [
    { js: "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js", worker: "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js" },
    { js: "https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js", worker: "https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js" },
    { js: "https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.min.js", worker: "https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.worker.min.js" }
  ];

  const tryLoad = (i) => new Promise((resolve, reject) => {
    if (i >= CDN_SOURCES.length) { reject(new Error("Could not load the PDF reader library - check your connection.")); return; }
    const src = CDN_SOURCES[i];
    const script = document.createElement("script");
    script.src = src.js;
    script.onload = () => {
      if (window.pdfjsLib) {
        window.pdfjsLib.GlobalWorkerOptions.workerSrc = src.worker;
        resolve(window.pdfjsLib);
      } else {
        script.remove();
        tryLoad(i + 1).then(resolve, reject);
      }
    };
    script.onerror = () => {
      script.remove();
      tryLoad(i + 1).then(resolve, reject);
    };
    document.head.appendChild(script);
  });

  _pdfjsPromise = tryLoad(0).catch((e) => { _pdfjsPromise = null; throw e; });
  return _pdfjsPromise;
}

// Fallback for PDFs where pdf.js finds no embedded text layer (scanned/
// image-based PDFs): render each page to a canvas and OCR it with Tesseract
// (already used elsewhere in the app for image uploads). This produces plain
// text, which is the only content format the /api/claude proxy actually
// understands - unlike sending the raw PDF bytes as an Anthropic-style
// "document" content block, which the Gemini-backed proxy cannot parse.
async function ocrPdfToText(pdfjsLib, pdf, maxPages, onProgress) {
  let text = "";
  const pages = Math.min(pdf.numPages, maxPages);
  // Reuse a single worker across all pages instead of recognize()'s default
  // behavior of spinning up a fresh worker (re-downloading the ~10MB language
  // model) for every single call. With 8 pages that was 8x redundant loads,
  // which is slow enough to blow past reasonable time budgets and made OCR
  // effectively fail on most real scans.
  const worker = await Tesseract.createWorker("eng");
  try {
    for (let i = 1; i <= pages; i++) {
      try {
        const page = await pdf.getPage(i);
        const viewport = page.getViewport({ scale: 2 });
        const canvas = document.createElement("canvas");
        canvas.width = viewport.width;
        canvas.height = viewport.height;
        const ctx = canvas.getContext("2d");
        await page.render({ canvasContext: ctx, viewport }).promise;
        if (onProgress) onProgress(i, pages);
        const { data } = await worker.recognize(canvas);
        if (data && data.text && data.text.trim()) {
          text += `\n--- Page ${i} ---\n${data.text}`;
        }
      } catch (e) {
        console.log("OCR page failed:", i, e && e.message);
        continue; // skip pages that fail to render/OCR, keep the rest
      }
    }
  } finally {
    try { await worker.terminate(); } catch {}
  }
  return text.trim();
}

// ============================================================
// ResourcesView - Fully Debugged
// ============================================================
function ResourcesView() {
  const [text, setText] = useState(() => {
    try { return window.sessionStorage.getItem("ascend_res_text") || ""; } catch { return ""; }
  });
  const [file, setFile] = useState(null);
  const [result, setResult] = useState(() => {
    try { return window.sessionStorage.getItem("ascend_res_result") || ""; } catch { return ""; }
  });
  const [busy, setBusy] = useState(false);
  const [stage, setStage] = useState("");
  const [err, setErr] = useState("");

  useEffect(() => {
    try { window.sessionStorage.setItem("ascend_res_text", text); } catch {}
  }, [text]);
  useEffect(() => {
    try { window.sessionStorage.setItem("ascend_res_result", result); } catch {}
  }, [result]);

  const run = async () => {
    setErr(""); 
    setResult("");
    
    const typed = text.trim();
    if (!typed && !file) { 
      setErr("Paste some content or choose a file first."); 
      return; 
    }
    
    setBusy(true);
    
    try {
      const ext = fileExt(file);
      
      // ============================================================
      // FIXED: Better PDF handling - extract text client-side
      // ============================================================
      if (file && ext === "pdf") {
        setStage("Reading your PDF...");
        
        try {
          // Load PDF.js library
          const pdfjsLib = await Promise.race([
            loadPDFJS(),
            new Promise((_, reject) => setTimeout(() => reject(new Error("Timed out loading the PDF reader library (it may be blocked by an ad blocker or firewall).")), 15000))
          ]);
          const arrayBuffer = await file.arrayBuffer();
          const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
          
          let fullText = "";
          const maxPages = Math.min(pdf.numPages, 20);
          
          for (let i = 1; i <= maxPages; i++) {
            try {
              const page = await pdf.getPage(i);
              const textContent = await page.getTextContent();
              const pageText = textContent.items.map(item => item.str).join(" ");
              if (pageText.trim()) {
                fullText += `\n--- Page ${i} ---\n${pageText}`;
              }
            } catch (pageErr) {
              // Skip pages that fail
              continue;
            }
          }
          
          if (!fullText.trim()) {
            throw new Error("Could not extract text from this PDF. It may be a scanned image-based PDF.");
          }
          
          // Truncate to reasonable size for AI
          if (fullText.length > 25000) {
            fullText = fullText.slice(0, 25000) + "\n... (truncated)";
          }
          
          setStage("Building your lesson...");
          
          // Use the extracted text with the AI
          const material = typed ? `${typed}\n\n${fullText}` : fullText;
          setResult(await callClaude(SOCRATIC_SYS, [{ role: "user", content: SOCRATIC_TASK + "\n\nMATERIAL:\n" + material }], 8000));
          
        } catch (pdfErr) {
          // The embedded-text extraction found nothing (commonly a scanned/
          // image-based PDF) or otherwise failed. Fall back to OCR-ing each
          // page image client-side, then send the resulting plain text to
          // the AI - this is the format the proxy actually supports.
          try {
            setStage("No text layer found - reading pages with OCR (this can take a minute)...");
            const pdfjsLib = await loadPDFJS();
            const arrayBuffer2 = await file.arrayBuffer();
            const pdf2 = await pdfjsLib.getDocument({ data: arrayBuffer2 }).promise;
            const ocrText = await Promise.race([
              ocrPdfToText(pdfjsLib, pdf2, 8, (done, total) => setStage(`Reading page ${done} of ${total} with OCR...`)),
              new Promise((_, reject) => setTimeout(() => reject(new Error("OCR took too long (over 90 seconds) and was stopped.")), 90000))
            ]);
            if (!ocrText) throw new Error("OCR ran but found no readable text on these pages.");
            let material = typed ? `${typed}\n\n${ocrText}` : ocrText;
            if (material.length > 25000) material = material.slice(0, 25000) + "\n... (truncated)";
            setStage("Building your lesson...");
            setResult(await callClaude(SOCRATIC_SYS, [{ role: "user", content: SOCRATIC_TASK + "\n\nMATERIAL:\n" + material }], 8000));
          } catch (ocrErr) {
            console.log("PDF OCR fallback failed:", ocrErr && ocrErr.message);
            const reason = (ocrErr && ocrErr.message) || "an unknown error";
            throw new Error(`This PDF's text could not be read automatically (${reason}). Please try copying the text directly from the PDF and pasting it instead.`);
          }
        }
        
      } else if (file) {
        // Handle other file types
        let material = typed;
        if (file && !material) {
          if (ext === "pptx") { 
            setStage("Opening your slides..."); 
            material = await pptxToText(file); 
          } else if (ext === "txt" || ext === "md") { 
            setStage("Reading your file..."); 
            material = await readTextFile(file); 
          } else {
            throw new Error("Supported files are PDF, PowerPoint (.pptx), and plain text. For .ppt or .doc, export to PDF first.");
          }
        }
        if (!material) throw new Error("That file had no readable text.");
        setStage("Building your lesson...");
        setResult(await callClaude(SOCRATIC_SYS, [{ role: "user", content: SOCRATIC_TASK + "\n\nMATERIAL:\n" + material }], 8000));
        
      } else {
        // Just text input
        setStage("Building your lesson...");
        setResult(await callClaude(SOCRATIC_SYS, [{ role: "user", content: SOCRATIC_TASK + "\n\nMATERIAL:\n" + typed }], 8000));
      }
      
    } catch (e) {
      const msg = e && e.message ? e.message : "The AI could not respond just now.";
      
      // ============================================================
      // FIXED: Better error messages for different issues
      // ============================================================
      if (msg.toLowerCase().includes("pdf") || msg.toLowerCase().includes("scan")) {
        setErr(`${msg}\n\nTry: Copy the text directly from the PDF and paste it instead.`);
      } else if (msg.includes("429") || msg.includes("rate") || msg.includes("busy") || msg.includes("overload")) {
        setErr("The AI service is busy right now. Please wait about 20 seconds and try again.");
      } else if (msg.toLowerCase().includes("connection") || msg.toLowerCase().includes("internet") || msg.toLowerCase().includes("network")) {
        setErr("Connection issue. Please check your internet and try again.");
      } else if (msg.toLowerCase().includes("timeout")) {
        setErr("The request timed out. The file may be too large. Try pasting the text directly instead.");
      } else {
        setErr(msg + " Please try again in a moment.");
      }
    } finally {
      // GUARANTEED reset - runs no matter what happened above (success,
      // caught error, or even an unexpected throw inside the catch block
      // itself), so the button can never get stuck disabled again.
      setStage("");
      setBusy(false);
    }
  };

  return (
    <div className="view">
      <div className="eyebrow">Resources</div>
      <h1 style={{ fontSize: "clamp(22px,4vw,28px)", margin: "6px 0 4px" }}>Bring your own material</h1>
      <p style={{ color: "var(--text-2)", marginTop: 0, maxWidth: "60ch" }}>Paste lecture notes or slides from the MELSSA Slides Group and ASCEND rebuilds it as a Socratic lesson - question, answer, crucial insight - so you learn the mechanism instead of skimming.</p>
      <div className="card" style={{ marginTop: 16 }}>
        <label className="field"><span>Paste your material</span>
          <textarea className="pastebox" value={text} onChange={(e) => setText(e.target.value)} placeholder="Paste lecture notes or slide text here, or upload a file below..." style={{ minHeight: "130px" }} />
        </label>
        <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
          <label className="btn btn-g" style={{ cursor: "pointer" }}>
            <Ic.upload p={16} /> Upload PDF, slides or text
            <input type="file" accept=".pdf,.pptx,.txt,.md" style={{ display: "none" }} onChange={(e) => { if (e.target.files[0]) { setFile(e.target.files[0]); setErr(""); } }} />
          </label>
          {file && (
            <span style={{ display: "flex", alignItems: "center", gap: 8, color: "var(--text-2)", fontSize: 13 }}>
              {file.name}
              <button className="iconbtn" style={{ width: 26, height: 26 }} onClick={() => setFile(null)} aria-label="Remove file"><Ic.x p={13} /></button>
            </span>
          )}
        </div>
        <p className="note-hint" style={{ marginTop: 10, lineHeight: 1.6 }}>PDF, PowerPoint (.pptx) and plain text are read directly. For older .ppt or .doc files, export to PDF first. With a PDF you can also type what to focus on above.</p>
        <button className="btn btn-a" style={{ marginTop: 12, width: "100%", padding: "12px" }} onClick={run} disabled={busy || (!text.trim() && !file)}>
          {busy ? (stage || "Working...") : "Break it down with ASCEND"}
        </button>
      </div>
      {err && <div className="card" style={{ marginTop: 14, color: "var(--text-2)", fontSize: 14, lineHeight: 1.6 }}>{err}</div>}
      {busy && <div className="card" style={{ marginTop: 14, display: "flex", alignItems: "center", gap: 12 }}><span className="dots"><span /><span /><span /></span><span style={{ color: "var(--text-3)", fontSize: 13.5 }}>{stage}</span></div>}
      {result && (
        <div className="card" style={{ marginTop: 14 }}>
          <div className="eyebrow" style={{ marginBottom: 10 }}>ASCEND breakdown</div>
          <AIText text={result} style={{ lineHeight: 1.8, fontSize: 15 }} />
        </div>
      )}
    </div>
  );
}

// ============================================================
// StudyToolsView - Fully Debugged
// ============================================================
function StudyToolsView() {
  const [tab, setTab] = useState("cards");
  const [courseId, setCourseId] = useState("ana");
  const [topic, setTopic] = useState("");
  const [material, setMaterial] = useState("");
  const [source, setSource] = useState("topic");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [cards, setCards] = useState(null);
  const [flipped, setFlipped] = useState({});
  const [map, setMap] = useState(null);
  const [flowCode, setFlowCode] = useState("");
  const [flowErr, setFlowErr] = useState("");
  const flowRef = useRef(null);

  const subject = source === "paste"
    ? `the following material:\n\n${material}`
    : `the topic "${topic || "this subject"}" in ${courseById(courseId).name} (${courseById(courseId).code}) for a KNUST first-year medical laboratory science student`;

  const genCards = async () => {
    if (busy) return;
    if (source === "topic" && !topic.trim()) { setErr("Type a topic first."); return; }
    if (source === "paste" && !material.trim()) { setErr("Paste some material first."); return; }
    setBusy(true); setErr(""); setCards(null); setFlipped({});
    try {
      const raw = await callClaude(
        "You create study flashcards for KNUST medical laboratory science students. Each card has a short front (a question, term, or prompt) and a concise back (the answer or definition). Focus on the most important, testable facts. Return ONLY a valid, compact JSON array, no prose, no markdown, no trailing commas. Only include facts you are confident are correct - do not invent specific numbers or classifications you are unsure of.",
        [{ role: "user", content: `Create 10 to 14 flashcards on ${subject}. Format: [{"front":"...","back":"..."}]. Keep each side short and precise.` }],
        3000
      );
      const arr = parseAIJson(raw);
      const clean = (Array.isArray(arr) ? arr : []).filter((x) => x && x.front && x.back);
      if (!clean.length) throw new Error("No cards came back - try again.");
      setCards(clean);
    } catch (e) {
      const msg = e && e.message ? e.message : "The AI could not respond just now.";
      if (msg.includes("429") || msg.includes("rate") || msg.includes("busy")) {
        setErr("The AI service is busy. Please wait a moment and try again.");
      } else {
        setErr(msg + " Please try again in a moment.");
      }
    } finally {
      setBusy(false);
    }
  };

  const genMap = async () => {
    if (busy) return;
    if (source === "topic" && !topic.trim()) { setErr("Type a topic first."); return; }
    if (source === "paste" && !material.trim()) { setErr("Paste some material first."); return; }
    setBusy(true); setErr(""); setMap(null);
    try {
      const raw = await callClaude(
        "You create hierarchical mind maps for KNUST medical laboratory science students. A mind map has a central topic, main branches, and sub-points under each. Return ONLY valid compact JSON, no prose, no markdown, no trailing commas. Only include facts you are confident are correct - do not invent specific numbers or classifications you are unsure of.",
        [{ role: "user", content: `Create a mind map of ${subject}. Format: {"central":"topic name","branches":[{"title":"main idea","points":["sub-point","sub-point"]}],"recommendations":["short study tip","short study tip"]}. Give 4 to 6 branches, each with 2 to 4 short points. "points" must be pure high-yield EXAM facts - specifically the 20% of content that appears in ~80% of exams: the definitions, values, classifications, enzymes and mechanisms an examiner keeps testing. Each point a crisp memorisable fact, never vague prose (good: "Glycolysis nets 2 ATP, 2 NADH, 2 pyruvate"; bad: "Glycolysis is important"). "recommendations" is a separate list of 2 to 4 short, concrete study/recall tips for using this map (e.g. "Redraw this from memory, then check against the branches").` }],
        3000
      );
      const data = parseAIJson(raw);
      if (!data || !data.central || !Array.isArray(data.branches)) throw new Error("bad shape");
      setMap(data);
    } catch (e) {
      const msg = e && e.message ? e.message : "The AI could not respond just now.";
      if (msg.includes("429") || msg.includes("rate") || msg.includes("busy")) {
        setErr("The AI service is busy. Please wait a moment and try again.");
      } else {
        setErr(msg + " Please try again in a moment.");
      }
    } finally {
      setBusy(false);
    }
  };

  const branchColors = ["var(--amber)", "#5B8DEF", "#4FB477", "#E86A6A", "#B07CE8", "#E0A32E"];

  const genFlow = async () => {
    if (busy) return;
    if (source === "topic" && !topic.trim()) { setErr("Type a topic first."); return; }
    if (source === "paste" && !material.trim()) { setErr("Paste some material first."); return; }
    setBusy(true); setErr(""); setFlowErr(""); setFlowCode("");
    try {
      const raw = await callClaude(
        "You write Mermaid flowchart code for KNUST medical laboratory science students. Output ONLY Mermaid code - no prose, no markdown fences. The first line must be exactly: flowchart TD. Wrap EVERY node label in double quotes, e.g. A[\"Glycolysis\"] --> B[\"Pyruvate\"]. Use curly braces only for yes/no decisions, e.g. C{\"Oxygen present?\"}. Never use parentheses, semicolons, or the word 'end' as a node id. Show the pathway as a clear step-by-step flow.",
        [{ role: "user", content: `Write a Mermaid flowchart of the process or pathway of ${subject}. Use 6 to 14 nodes. Every label in double quotes. Output only the code.` }],
        1500
      );
      const code = sanitizeMermaid(raw);
      if (!/^flowchart\s+(TD|TB|LR|RL|BT)/i.test(code)) throw new Error("The diagram could not be built - try again.");
      setFlowCode(code);
    } catch (e) {
      const msg = e && e.message ? e.message : "The AI could not respond just now.";
      if (msg.includes("429") || msg.includes("rate") || msg.includes("busy")) {
        setErr("The AI service is busy. Please wait a moment and try again.");
      } else {
        setErr(msg + " Please try again in a moment.");
      }
    } finally {
      setBusy(false);
    }
  };

  useEffect(() => {
    if (!flowCode || tab !== "flow") return;
    let cancelled = false;
    (async () => {
      const mermaid = await loadMermaid().catch(() => null);
      if (!mermaid || cancelled) { if (!cancelled) setFlowErr("Could not load the diagram library - check your connection."); return; }
      const tryRender = async (src) => {
        const id = "flow-" + Math.random().toString(36).slice(2);
        const { svg } = await mermaid.render(id, src);
        return svg;
      };
      try {
        let svg;
        try { svg = await tryRender(flowCode); }
        catch { svg = await tryRender(stripMermaid(flowCode)); } // fallback pass
        if (!cancelled && flowRef.current) { flowRef.current.innerHTML = svg; setFlowErr(""); }
      } catch (e) {
        if (!cancelled) setFlowErr("This diagram did not render cleanly. Tap Build again for a fresh version.");
      }
    })();
    return () => { cancelled = true; };
  }, [flowCode, tab]);

  return (
    <div className="view">
      <div className="eyebrow">Study tools</div>
      <h1 style={{ fontSize: "clamp(22px,4vw,28px)", margin: "6px 0 4px" }}>Flashcards and mind maps</h1>
      <p style={{ color: "var(--text-2)", marginTop: 0, maxWidth: "58ch" }}>Turn any topic or your own notes into flashcards for active recall, or a mind map to see how the ideas connect. Both are generated fresh by ASCEND.</p>

      <div className="tabs">
        <button className={"tab " + (tab === "cards" ? "on" : "")} onClick={() => { setTab("cards"); setErr(""); }}>Flashcards</button>
        <button className={"tab " + (tab === "map" ? "on" : "")} onClick={() => { setTab("map"); setErr(""); }}>Mind map</button>
        <button className={"tab " + (tab === "flow" ? "on" : "")} onClick={() => { setTab("flow"); setErr(""); }}>Flow diagram</button>
      </div>

      <div className="card" style={{ marginTop: 12 }}>
        <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
          <button className="btn btn-sm" style={{ background: source === "topic" ? "var(--amber)" : "var(--bg-3)", color: source === "topic" ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }} onClick={() => setSource("topic")}>From a topic</button>
          <button className="btn btn-sm" style={{ background: source === "paste" ? "var(--amber)" : "var(--bg-3)", color: source === "paste" ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }} onClick={() => setSource("paste")}>From my notes</button>
        </div>

        {source === "topic" ? (
          <>
            <label className="eyebrow" style={{ display: "block", marginBottom: 8 }}>Course</label>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
              {COURSES.map((c) => (
                <button key={c.id} className="btn btn-sm" style={{ background: courseId === c.id ? "var(--amber)" : "var(--bg-3)", color: courseId === c.id ? "#1B1405" : "var(--text-2)", border: "1px solid var(--line)" }} onClick={() => setCourseId(c.id)}>{c.code}</button>
              ))}
            </div>
            <label className="eyebrow" style={{ display: "block", marginBottom: 8 }}>Topic</label>
            <input className="auth-input" value={topic} placeholder="e.g. Homeostasis, or Amino acids" onChange={(e) => setTopic(e.target.value)} />
          </>
        ) : (
          <>
            <label className="eyebrow" style={{ display: "block", marginBottom: 8 }}>Paste your notes or lecture material</label>
            <textarea className="pastebox" value={material} placeholder="Paste any notes, slide text or a paragraph here..." onChange={(e) => setMaterial(e.target.value)} />
          </>
        )}

        <div style={{ marginTop: 14 }}>
          {tab === "cards"
            ? <button className="btn btn-a" onClick={genCards} disabled={busy}>{busy ? "Making your flashcards..." : "Make flashcards"} <Ic.ai p={16} /></button>
            : tab === "map"
            ? <button className="btn btn-a" onClick={genMap} disabled={busy}>{busy ? "Building your mind map..." : "Build mind map"} <Ic.ai p={16} /></button>
            : <button className="btn btn-a" onClick={genFlow} disabled={busy}>{busy ? "Drawing your flow diagram..." : "Build flow diagram"} <Ic.ai p={16} /></button>}
        </div>
      </div>

      {err && <div className="card" style={{ marginTop: 14, borderColor: "var(--line-2)", color: "var(--text-2)", fontSize: 14 }}>{err}</div>}
      {busy && <div className="card" style={{ marginTop: 14 }}><span className="dots"><span /><span /><span /></span></div>}

      {!busy && !err && tab === "cards" && !cards && (
        <div className="card" style={{ marginTop: 14, color: "var(--text-2)", fontSize: 14 }}>No flashcards yet. Pick a topic or paste material above, then tap "Make flashcards".</div>
      )}
      {!busy && !err && tab === "map" && !map && (
        <div className="card" style={{ marginTop: 14, color: "var(--text-2)", fontSize: 14 }}>No mind map yet. Pick a topic or paste material above, then tap "Build mind map".</div>
      )}
      {!busy && !err && tab === "flow" && !flowCode && (
        <div className="card" style={{ marginTop: 14, color: "var(--text-2)", fontSize: 14 }}>No flow diagram yet. Pick a topic or paste material above, then tap "Build flow diagram".</div>
      )}

      {tab === "cards" && cards && (
        <>
          <p className="note-hint" style={{ margin: "16px 0 10px" }}>Tap a card to flip it. Say the answer out loud before you flip - that is the recall that builds memory.</p>
          <div className="grid g2">
            {cards.map((c, k) => (
              <button key={k} className="card hover" style={{ minHeight: 120, textAlign: "left", display: "flex", flexDirection: "column", justifyContent: "center", cursor: "pointer", border: flipped[k] ? "1px solid var(--amber)" : "1px solid var(--line)" }} onClick={() => setFlipped({ ...flipped, [k]: !flipped[k] })}>
                <div className="mono" style={{ fontSize: 10.5, color: flipped[k] ? "var(--amber)" : "var(--text-3)", marginBottom: 8 }}>{flipped[k] ? "ANSWER" : "TAP TO FLIP"}</div>
                <div style={{ fontWeight: flipped[k] ? 500 : 650, fontSize: 15, lineHeight: 1.5, color: flipped[k] ? "var(--text-2)" : "var(--text)" }}>{flipped[k] ? c.back : c.front}</div>
              </button>
            ))}
          </div>
        </>
      )}

      {tab === "map" && map && (
        <div className="card" style={{ marginTop: 16 }}>
          <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 4 }}>
            <button
              className="btn btn-sm"
              style={{ background: "var(--bg-3)", color: "var(--text-2)", border: "1px solid var(--line)" }}
              onClick={() => downloadMindMapPDF(map).catch(() => setErr("Could not build the PDF - try again."))}
            >
              Download as PDF
            </button>
          </div>
          <div style={{ textAlign: "center", marginBottom: 18 }}>
            <span style={{ display: "inline-block", background: "var(--amber)", color: "#1B1405", fontWeight: 750, fontSize: 16, padding: "10px 20px", borderRadius: 12 }}>{map.central}</span>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            {map.branches.map((b, k) => (
              <div key={k} style={{ borderLeft: `3px solid ${branchColors[k % branchColors.length]}`, paddingLeft: 14 }}>
                <div style={{ fontWeight: 700, fontSize: 15, color: branchColors[k % branchColors.length], marginBottom: 6 }}>{b.title}</div>
                <ul style={{ margin: 0, paddingLeft: 18, color: "var(--text-2)", fontSize: 14, lineHeight: 1.7 }}>
                  {(b.points || []).map((p, j) => <li key={j}>{p}</li>)}
                </ul>
              </div>
            ))}
          </div>
          {Array.isArray(map.recommendations) && map.recommendations.length > 0 && (
            <div style={{ marginTop: 18, paddingTop: 14, borderTop: "1px solid var(--line)" }}>
              <div className="eyebrow" style={{ marginBottom: 8 }}>Recommendations</div>
              <ul style={{ margin: 0, paddingLeft: 0, listStyle: "none", display: "flex", flexDirection: "column", gap: 7 }}>
                {map.recommendations.map((r, ri) => (
                  <li key={ri} style={{ display: "flex", gap: 9, alignItems: "flex-start", color: "var(--text)", fontSize: 14, lineHeight: 1.55 }}>
                    <span style={{ color: "var(--amber)", flexShrink: 0, marginTop: 6, width: 5, height: 5, borderRadius: "50%", background: "var(--amber)" }} />
                    <span>{r}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}
      {tab === "flow" && flowCode && (
        <>
          <p className="note-hint" style={{ margin: "16px 0 10px" }}>Follow the arrows to see how each step leads to the next. Rebuild for a fresh version any time.</p>
          <div className="card" style={{ marginTop: 4, overflowX: "auto" }}>
            <div ref={flowRef} style={{ display: "flex", justifyContent: "center", minHeight: 60 }} />
            {flowErr && <div style={{ color: "var(--text-2)", fontSize: 13.5, marginTop: 10 }}>{flowErr}</div>}
          </div>
        </>
      )}
    </div>
  );
}
/* ------------------------------- home ----------------------------------- */
// A daily-rotating motivational line for the home screen. Deterministic by date,
// so every student sees the same quote each day and it changes at midnight.
const MOTIVATION_QUOTES = [
  { q: "The lab does not care how you feel today. Show up anyway - competence is built on the days you did not want to.", a: "ASCEND" },
  { q: "One accurate result can change a diagnosis. One more topic tonight can change your grade. Both are worth it.", a: "ASCEND" },
  { q: "You are not behind. You are exactly one focused hour away from understanding the thing you feared.", a: "ASCEND" },
  { q: "Discipline is choosing what you want most over what you want now.", a: "Abraham Lincoln" },
  { q: "Small daily improvements are the key to staggering long-term results.", a: "Robin Sharma" },
  { q: "The expert in anything was once a beginner who refused to quit.", a: "Helen Hayes" },
  { q: "A smooth sea never made a skilled sailor. Hard topics are making you a scientist.", a: "Franklin D. Roosevelt" },
  { q: "Do not wish it were easier. Wish you were better.", a: "Jim Rohn" },
  { q: "Every slide you master today is a patient you serve better tomorrow.", a: "ASCEND" },
  { q: "Success is the sum of small efforts repeated day in and day out.", a: "Robert Collier" },
  { q: "The pain of discipline weighs ounces. The pain of regret weighs tons.", a: "Jim Rohn" },
  { q: "You do not have to be extraordinary to start. You have to start to become extraordinary.", a: "ASCEND" },
  { q: "Fall seven times, stand up eight.", a: "Japanese proverb" },
  { q: "Knowledge is the one thing no one can take from you. Stack it daily.", a: "ASCEND" },
  { q: "The two best days are the day you started and the day you understood why.", a: "ASCEND" },
  { q: "Slow progress is still progress. Do not stop.", a: "ASCEND" },
  { q: "Study while others sleep; work while others waste time. First Class is built quietly.", a: "ASCEND" },
  { q: "Your future patients are counting on the questions you answer tonight.", a: "ASCEND" },
  { q: "Motivation gets you started. Habit keeps you going. Build the habit.", a: "Jim Ryun" },
  { q: "It always seems impossible until it is done.", a: "Nelson Mandela" },
  { q: "If you are tired, learn to rest, not to quit.", a: "Banksy" },
  { q: "The person who moves a mountain begins by carrying away small stones.", a: "Confucius" },
  { q: "You are allowed to be both a masterpiece and a work in progress.", a: "ASCEND" },
  { q: "Consistency beats intensity. Ten minutes today beats three hours next week.", a: "ASCEND" },
  { q: "Doubt kills more dreams than failure ever will. Open the topic anyway.", a: "Suzy Kassem" },
  { q: "The climb to First Class is together. No gatekeeping. Keep moving.", a: "ASCEND" },
];

function motivationForToday() {
  const start = new Date(new Date().getFullYear(), 0, 0);
  const diff = new Date() - start;
  const dayOfYear = Math.floor(diff / 86400000);
  return MOTIVATION_QUOTES[dayOfYear % MOTIVATION_QUOTES.length];
}

// Dismissible weekly summary shown on the home screen. Shows once per
// calendar week per user (tracked via weekKey in localStorage), then stays
// hidden until the following week rolls around - it never nags on every
// resume the way a plain "always show" card would.
function WeeklyRecapCard({ app }) {
  const wk = weekKey();
  const storageKey = "ascend_recap_dismissed_" + (app.supaUid || app.progress.name || "guest");
  const [dismissed, setDismissed] = useState(() => {
    try { return localStorage.getItem(storageKey) === wk; } catch { return false; }
  });
  const recap = buildWeeklyRecap(app.progress, app.supaUid);

  if (dismissed) return null;

  const dismiss = () => {
    setDismissed(true);
    try { localStorage.setItem(storageKey, wk); } catch {}
  };

  return (
    <div className="card" style={{ marginTop: 16, borderLeft: "3px solid var(--amber)", position: "relative" }}>
      <button
        onClick={dismiss}
        aria-label="Dismiss weekly recap"
        style={{ position: "absolute", top: 10, right: 10, background: "none", border: "none", cursor: "pointer", color: "var(--text-3)", padding: 4, display: "flex" }}
      >
        <Ic.x p={16} />
      </button>
      <div className="eyebrow" style={{ color: "var(--amber)", marginBottom: 10 }}>Your week</div>
      <div style={{ display: "flex", gap: 22, flexWrap: "wrap" }}>
        <div>
          <div className="mono" style={{ fontWeight: 800, fontSize: 22, color: "var(--text)" }}>{recap.daysActive}<span style={{ fontSize: 13, color: "var(--text-3)", fontWeight: 600 }}> / 7</span></div>
          <div style={{ fontSize: 12, color: "var(--text-3)", marginTop: 2 }}>days active</div>
        </div>
        {recap.xpThisWeek !== null && (
          <div>
            <div className="mono" style={{ fontWeight: 800, fontSize: 22, color: "var(--amber)" }}>+{recap.xpThisWeek}</div>
            <div style={{ fontSize: 12, color: "var(--text-3)", marginTop: 2 }}>XP earned</div>
          </div>
        )}
        <div>
          <div className="mono" style={{ fontWeight: 800, fontSize: 22, color: "var(--text)" }}>{recap.streak}</div>
          <div style={{ fontSize: 12, color: "var(--text-3)", marginTop: 2 }}>day streak</div>
        </div>
      </div>
    </div>
  );
}

